import inspector from "node:inspector";
const sessions = new Map();
const queue = [];
let callbacks;
let scheduled = false;
/** Wire the guest's exported callbacks interface. Call once, after instantiation. */
export function attachCallbacks(exports) {
    callbacks = exports;
    if (queue.length > 0) {
        schedule();
    }
}
function schedule() {
    if (scheduled) {
        return;
    }
    scheduled = true;
    setImmediate(flush);
}
function flush() {
    scheduled = false;
    if (!callbacks) {
        // Still waiting for attachCallbacks; a later attach re-schedules.
        return;
    }
    const jobs = queue.splice(0, queue.length);
    for (const job of jobs) {
        job();
    }
}
function enqueue(job) {
    queue.push(job);
    if (callbacks) {
        schedule();
    }
}
/** Wrap a caught host error as the WIT `failed` variant so it crosses the boundary as an `err`. */
function failed(error) {
    const value = error;
    throw {
        tag: "failed",
        val: {
            code: typeof value?.code === "string" ? value.code : "ERR_JCO_INSPECTOR_HOST",
            message: typeof value?.message === "string" ? value.message : String(error),
        },
    };
}
function serializeError(error) {
    const value = error;
    return JSON.stringify({
        code: typeof value?.code === "string" ? value.code : undefined,
        message: typeof value?.message === "string" ? value.message : String(error),
    });
}
function requireSession(id) {
    const state = sessions.get(id);
    if (!state) {
        throw { tag: "no-such-session", val: id };
    }
    return state;
}
export const open = (port, host, wait) => {
    try {
        inspector.open(port, host, wait);
    }
    catch (error) {
        failed(error);
    }
};
export const close = () => {
    try {
        inspector.close();
    }
    catch (error) {
        failed(error);
    }
};
export const url = () => {
    try {
        return inspector.url();
    }
    catch (error) {
        failed(error);
    }
};
export const waitForDebugger = () => {
    try {
        inspector.waitForDebugger();
    }
    catch (error) {
        failed(error);
    }
};
export const consoleCall = (context, method, argsJson) => {
    try {
        const args = JSON.parse(argsJson);
        const consoleApi = inspector.console;
        const target = context === undefined ? consoleApi : consoleApi.context(context);
        const fn = target[method];
        if (typeof fn === "function") {
            fn.apply(target, args);
        }
    }
    catch (error) {
        failed(error);
    }
};
export const sessionConnect = (id, kind, listener) => {
    const session = new inspector.Session();
    try {
        connect(session, kind);
    }
    catch (error) {
        failed(error);
    }
    const state = { session, listenerId: listener };
    sessions.set(id, state);
    session.on("inspectorNotification", (message) => {
        enqueue(() => {
            const target = resolveListener(state);
            target?.notify(message.method, JSON.stringify(message.params ?? {}));
        });
    });
};
function connect(session, kind) {
    if (kind === "main-thread") {
        session.connectToMainThread();
    }
    else {
        session.connect();
    }
}
function resolveListener(state) {
    if (!state.listener) {
        state.listener = callbacks?.takeNotificationListener(state.listenerId);
    }
    return state.listener;
}
export const sessionPost = (id, method, paramsJson, callback) => {
    const state = requireSession(id);
    const params = paramsJson === undefined ? undefined : JSON.parse(paramsJson);
    // Node fires the callback synchronously for in-isolate methods. Capture that: if it lands before
    // post() returns, hand the response straight back so an awaited post never needs a re-entrant
    // callback. Only a genuinely deferred response goes through the post-callback resource.
    let returned = false;
    let synchronous;
    const handle = (error, result) => {
        if (!returned) {
            synchronous = toResponse(error, result);
            return;
        }
        if (callback === undefined) {
            return;
        }
        enqueue(() => {
            const resource = callbacks?.takePostCallback(callback);
            if (!resource) {
                return;
            }
            if (error) {
                resource.done(serializeError(error), undefined);
            }
            else {
                resource.done(undefined, JSON.stringify(result ?? {}));
            }
        });
    };
    try {
        if (params === undefined) {
            state.session.post(method, (error, result) => handle(error, result));
        }
        else {
            state.session.post(method, params, (error, result) => handle(error, result));
        }
    }
    catch (error) {
        failed(error);
    }
    returned = true;
    return synchronous;
};
/** Build the WIT `command-response` for a synchronously-delivered `(err, result)` pair. */
function toResponse(error, result) {
    if (error) {
        const value = error;
        return {
            tag: "failed",
            val: {
                code: typeof value?.code === "string" ? value.code : "ERR_INSPECTOR_COMMAND",
                message: typeof value?.message === "string" ? value.message : String(error),
            },
        };
    }
    return { tag: "ok", val: result === undefined ? undefined : JSON.stringify(result) };
}
export const sessionDisconnect = (id) => {
    const state = sessions.get(id);
    if (!state) {
        return;
    }
    sessions.delete(id);
    try {
        state.session.disconnect();
    }
    catch (error) {
        failed(error);
    }
};
export const emit = (target, event, paramsJson) => {
    try {
        const params = JSON.parse(paramsJson);
        const namespace = broadcastNamespace(target);
        const fn = namespace[event];
        if (typeof fn === "function") {
            fn.call(namespace, params);
        }
    }
    catch (error) {
        failed(error);
    }
};
function broadcastNamespace(target) {
    const inspectorAny = inspector;
    return target === "network" ? inspectorAny.Network : inspectorAny.DOMStorage;
}
export const putNetworkResource = (url, data) => {
    try {
        const resources = inspector.NetworkResources;
        resources?.put(url, data);
    }
    catch (error) {
        failed(error);
    }
};
export default {
    open,
    close,
    url,
    waitForDebugger,
    consoleCall,
    sessionConnect,
    sessionPost,
    sessionDisconnect,
    emit,
    putNetworkResource,
    attachCallbacks,
};
